using System;using System.IO;using System.IO.MemoryMappedFiles;using System.Diagnostics;using System.Collections.Generic;using System.Threading;using System.Security.AccessControl;using System.Security.Principal;using ThinkPadModesV3;
internal sealed class ZeroCalibrationSession:ILenovoSession {
 readonly Process parent;readonly MemoryMappedFile memory;readonly MemoryMappedViewAccessor view;
 internal static bool Requested{get{return Environment.GetEnvironmentVariable("TPM_ZERO_CALIBRATION")=="1";}}
 internal static long Tick{get{return CoolingPaths.Tick;}}
 internal ZeroCalibrationSession(){parent=Process.GetProcessById(Int32.Parse(Environment.GetEnvironmentVariable("TPM_LAB_GUARD_PID")));if(Digest.Of(parent.MainModule.FileName)!=Digest.Of(typeof(ZeroCalibrationSession).Assembly.Location))throw new IOException("Calibration guardian differs");memory=MemoryMappedFile.OpenExisting(Environment.GetEnvironmentVariable("TPM_LAB_GUARD_NAME"));view=memory.CreateViewAccessor();view.Write(24,(long)Process.GetCurrentProcess().Id);Pulse();}
 public bool Continuous{get{return true;}}public bool Completed{get{return false;}}
 public void Pulse(){if(parent.HasExited||Tick-view.ReadInt64(0)>2500||view.ReadInt64(64)!=0)throw new IOException("Calibration guardian missing or stopped");view.Write(8,Tick);}
 public void Busy(bool b){view.Write(16,b?1L:0L);}
 public void Sample(object raw){Pulse();var d=(Dictionary<string,object>)raw;int mode=Convert.ToInt32(d["Mode"]);if(mode!=0&&mode!=128)throw new IOException("Calibration mode changed externally: "+mode);view.Write(40,Convert.ToInt32(d["Fan1"]));view.Write(44,Convert.ToInt32(d["Fan2"]));view.Write(48,mode);view.Write(32,Tick);view.Write(56,view.ReadInt64(56)+1);}
 public void Dispose(){try{using(var ec=new LenovoOemTransport(true))ec.SetBothOem(128);if(parent.HasExited){ForcedZeroReader.StopBurnPid((int)view.ReadInt64(72));string journal=Environment.GetEnvironmentVariable("TPM_ZERO_JOURNAL");if(!String.IsNullOrEmpty(journal)&&File.Exists(journal))new ZeroPowerLease(journal,true);}}finally{view.Dispose();memory.Dispose();parent.Dispose();}}
}
internal sealed class ForcedZeroReader:IDisposable {
 readonly MemoryMappedFile memory;readonly MemoryMappedViewAccessor view;readonly Process bridge;readonly Thread heartbeat;volatile bool stopped,guardReady;volatile string guardError;long mainPulse;bool disposed;
 internal void Pulse(){System.Threading.Interlocked.Exchange(ref mainPulse,CoolingPaths.Tick);}
 internal int BurnPid{set{view.Write(72,(long)value);}}
 internal int Pid{get{return (int)view.ReadInt64(24);}}
 internal long Sequence{get{return view.ReadInt64(56);}}
 internal bool StopRequested{get{return view.ReadInt64(64)!=0;}}
 internal ForcedZeroReader(string folder,bool direct=false){string name="Local\\ThinkPadModes.ZeroCalibration."+Guid.NewGuid().ToString("N");var acl=new MemoryMappedFileSecurity();acl.SetAccessRuleProtection(true,false);foreach(string sid in new[]{"S-1-5-18","S-1-5-32-544"})acl.AddAccessRule(new AccessRule<MemoryMappedFileRights>(new SecurityIdentifier(sid),MemoryMappedFileRights.FullControl,AccessControlType.Allow));memory=MemoryMappedFile.CreateNew(name,128,MemoryMappedFileAccess.ReadWrite,MemoryMappedFileOptions.None,acl,HandleInheritability.None);view=memory.CreateViewAccessor();view.Write(0,CoolingPaths.Tick);Pulse();var start=new ProcessStartInfo(typeof(ForcedZeroReader).Assembly.Location,(direct?"--direct-rpm ":"--sdk ")+"\""+Path.Combine(folder,"sdk-"+Guid.NewGuid().ToString("N")+".json")+"\" "+name+" "+Process.GetCurrentProcess().Id){UseShellExecute=false,CreateNoWindow=true};start.EnvironmentVariables["TPM_ZERO_CALIBRATION"]="1";start.EnvironmentVariables["TPM_ZERO_JOURNAL"]=Path.Combine(folder,"cpu-lease.json");bridge=Process.Start(start);heartbeat=new Thread(()=>{try{using(var cpu=new CalibrationCpu())using(var gpu=new NvmlTelemetry()){guardReady=true;while(!stopped){double c=cpu.Temperature();var g=gpu.Read()["GpuTemperature"];if(g.Status!="valid"||!g.Value.HasValue||c>=90||g.Value.Value>=80||CoolingPaths.Tick-System.Threading.Interlocked.Read(ref mainPulse)>4500)throw new IOException("Gardien thermique indépendant90CPU/80GPU ou cœur de contrôle absent");view.Write(0,CoolingPaths.Tick);Thread.Sleep(100);}}}catch(Exception e){guardError=e.Message;view.Write(64,1L);try{EmergencyAuto(Pid);StopBurnPid((int)view.ReadInt64(72));string journal=Path.Combine(folder,"cpu-lease.json");if(File.Exists(journal))new ZeroPowerLease(journal,true);}catch(Exception recovery){guardError+=" ; secours: "+recovery.Message;}stopped=true;}}){IsBackground=true};heartbeat.Start();}
 internal CoolingSnapshot Snapshot(){if(guardError!=null)throw new IOException(guardError);long age=CoolingPaths.Tick-view.ReadInt64(32);if(bridge.HasExited)throw new IOException("Lecteur SDK arrêté: "+bridge.ExitCode);if(view.ReadInt64(56)==0||age<0||age>6000)throw new IOException("RPM Lenovo absents/périmés");int mode=view.ReadInt32(48);return new CoolingSnapshot{Request=mode==0?"Zero":"Auto",Actual=mode==0?"Zero":"Auto",Fan1=view.ReadInt32(40),Fan2=view.ReadInt32(44),FrameAgeMs=age,FanUTC=DateTime.UtcNow.AddMilliseconds(-age).ToString("o"),Faulted=false,Pending=false};}
 internal void Set(byte mode){if(mode!=0&&mode!=128)throw new ArgumentException();if(mode==0&&(!guardReady||guardError!=null||stopped))throw new IOException("Gardien0dB indisponible");using(var ec=new LenovoOemTransport(true,mode==0))ec.SetBothOem(mode);}
 internal static void StopBurnPid(int pid){if(pid<=0)return;try{using(var p=Process.GetProcessById(pid)){if(!p.HasExited){if(Digest.Of(p.MainModule.FileName)!=Digest.Of(typeof(ForcedZeroReader).Assembly.Location))throw new IOException("Burn identity differs");p.Kill();p.WaitForExit();}}}catch(ArgumentException){}}
 internal static void EmergencyAuto(int pid){if(pid>0)try{using(var p=Process.GetProcessById(pid)){if(!p.HasExited){string file=p.MainModule.FileName;string root=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.ProgramFiles),@"Lenovo\Lenovo Diagnostics Evolution")+Path.DirectorySeparatorChar;if((!String.Equals(Path.GetFullPath(file),Path.GetFullPath(typeof(ForcedZeroReader).Assembly.Location),StringComparison.OrdinalIgnoreCase)&&(!file.StartsWith(root,StringComparison.OrdinalIgnoreCase)||!Path.GetFileName(file).StartsWith("ThinkPadModes-LsdkReadProbe-",StringComparison.Ordinal)))||Digest.Of(file)!=Digest.Of(typeof(ForcedZeroReader).Assembly.Location))throw new IOException("SDK recovery identity differs");p.Kill();p.WaitForExit();}}}catch(ArgumentException){}using(var m=new Mutex(false,@"Global\Access_EC")){bool held=false;try{try{held=m.WaitOne(2000);}catch(AbandonedMutexException){held=true;}if(!held)throw new IOException("Own SDK mutex not released");}finally{if(held)m.ReleaseMutex();}}using(var ec=new LenovoOemTransport(true))ec.SetBothOem(128);}
 public void Dispose(){if(disposed)return;stopped=true;heartbeat.Join(3000);try{view.Write(64,1L);if(!bridge.WaitForExit(3000)){EmergencyAuto(Pid);if(!bridge.WaitForExit(3000)){bridge.Kill();bridge.WaitForExit();}}using(var ec=new LenovoOemTransport(true))ec.SetBothOem(128);}finally{stopped=true;heartbeat.Join(1000);bridge.Dispose();view.Dispose();memory.Dispose();disposed=true;}}
}
